import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    var v1 = scanner.nextInt()
    val v2 = scanner.nextInt()
    var t = scanner.nextInt()
    val d = scanner.nextInt()

    var path = 0L

    while (t > 0) {
        path += v1
        val maxSpeed = v2 + d * (t - 2)

        if (maxSpeed > v1) {
            v1 = Math.min(v1 + d, maxSpeed)
        } else if (maxSpeed < v1) {
            v1 = Math.max(v1 - d, maxSpeed)
        }

        t--
    }

    println(path)
}

