import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val writer = PrintWriter(System.out)

    val v1 = scanner.nextInt()
    val v2 = scanner.nextInt()
    var t = scanner.nextInt()
    val d = scanner.nextInt()

    var path: Long = 0
    var currentV1 = v1

    while (t > 0) {
        path += currentV1
        val maxSpeed = v2 + d * (t - 2)

        if (maxSpeed > currentV1) {
            if (currentV1 + d > maxSpeed) {
                currentV1 = maxSpeed
            } else {
                currentV1 += d
            }
        } else if (maxSpeed < currentV1) {
            if (currentV1 - d < maxSpeed) {
                currentV1 = maxSpeed
            } else {
                currentV1 -= d
            }
        }
        t--
    }

    writer.println(path)
    writer.flush()
