fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val tokenizer = StringTokenizer(br.readText())

    fun nextInt() = tokenizer.nextToken().toInt()

    var v1 = nextInt()
    val v2 = nextInt()
    val t = nextInt()
    val d = nextInt()

    var path = 0
    var time = t

    while (time > 0) {
        path += v1
        val maxSpeed = v2 + d * (time - 2)
        if (maxSpeed > v1) {
            v1 = if (v1 + d > maxSpeed) maxSpeed else v1 + d
        } else if (maxSpeed < v1) {
            v1 = if (v1 - d < maxSpeed) maxSpeed else v1 - d
        }
        time--
    }

    println(path)
}

